#include <stdio.h>
#include <string.h>

int levenshtein_distance(char *s1, char *s2) {
    int m = strlen(s1), n = strlen(s2), i, j;
    int dp[m + 1][n + 1];

    for (i = 0; i <= m; i++)
        dp[i][0] = i;
    for (j = 0; j <= n; j++)
        dp[0][j] = j;

    for (i = 1; i <= m; i++)
        for (j = 1; j <= n; j++)
            if (s1[i - 1] == s2[j - 1])
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = 1 + ((dp[i - 1][j] < dp[i][j - 1]) ? dp[i - 1][j] : dp[i][j - 1]);

    return dp[m][n];
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE: %s <string1> <string2>\n", argv[0]);
        return 1;
    }
    if (strlen(argv[1]) > 40 || strlen(argv[2]) > 40) {
        printf("TOO_LONG\n");
        return 1;
    }
    printf("%d\n", levenshtein_distance(argv[1], argv[2]));
    return 0;
}
